/** Hue in degrees, saturation/value in percent, and opacity in [0, 1]. */
export type Hsva = { h: number; s: number; v: number; a: number };
/** Red, green and blue in [0, 255], and opacity in [0, 1]. */
export type Rgba = { r: number; g: number; b: number; a: number };

export function hsvaToRgba(color: Hsva): Rgba {
  const brightness = color.v / 100;
  const chroma = brightness * color.s / 100;
  const sector = ((color.h % 360) + 360) % 360 / 60;
  const secondary = chroma * (1 - Math.abs(sector % 2 - 1));
  const channels = sector < 1 ? [chroma, secondary, 0]
    : sector < 2 ? [secondary, chroma, 0]
    : sector < 3 ? [0, chroma, secondary]
    : sector < 4 ? [0, secondary, chroma]
    : sector < 5 ? [secondary, 0, chroma] : [chroma, 0, secondary];
  const floor = brightness - chroma;
  const [r, g, b] = channels.map(channel => Math.round((channel + floor) * 255));
  return { r: r!, g: g!, b: b!, a: color.a };
}

/** Achromatic colors retain the otherwise unrepresentable editing channels. */
export function rgbaToHsva(color: Rgba, previous?: Hsva): Hsva {
  const channels = [color.r, color.g, color.b];
  const light = Math.max(...channels), dark = Math.min(...channels), span = light - dark;
  let hue = previous?.h ?? 0;
  if (span > 0) {
    const dominant = channels.indexOf(light);
    const angles = [
      (color.g - color.b) / span,
      (color.b - color.r) / span + 2,
      (color.r - color.g) / span + 4,
    ];
    hue = (angles[dominant]! * 60 + 360) % 360;
  }
  return {
    h: hue,
    s: light === 0 ? (previous?.s ?? 0) : 100 * span / light,
    v: 100 * light / 255,
    a: color.a,
  };
}

export function parseHex(input: string): Rgba | null {
  const digits = input.trim().replace(/^#/, "");
  if (![3, 4, 6, 8].includes(digits.length) || /[^0-9a-f]/i.test(digits)) return null;
  const expanded = digits.length < 5 ? Array.from(digits, digit => digit.repeat(2)).join("") : digits;
  const bytes = expanded.match(/../g)!.map(pair => Number.parseInt(pair, 16));
  return { r: bytes[0]!, g: bytes[1]!, b: bytes[2]!, a: bytes.length === 4 ? Math.round(bytes[3]! / 255 * 100) / 100 : 1 };
}

export function formatHex(color: Rgba): string {
  const components = [color.r, color.g, color.b];
  if (color.a < 1) components.push(color.a * 255);
  return "#" + components.map(component => Math.round(component).toString(16).padStart(2, "0")).join("");
}

export function hsvToHsl(color: Hsva) {
  const value = color.v / 100;
  const low = value * (1 - color.s / 100);
  const lightness = (value + low) / 2;
  const range = Math.min(lightness, 1 - lightness);
  return { h: color.h, s: range === 0 ? 0 : 100 * (value - lightness) / range, l: 100 * lightness };
}

export function hslToHsv(h: number, s: number, l: number, previous: Hsva, a: number): Hsva {
  const lightness = l / 100;
  const chroma = (1 - Math.abs(2 * lightness - 1)) * s / 100;
  const value = lightness + chroma / 2;
  return { h, s: value === 0 ? previous.s : chroma / value * 100, v: value * 100, a };
}

import { computed, inject, onBeforeUnmount, ref, watch, type Ref } from "vue";
import { motionValue, useSpring, useTransform } from "motion-v";
import { useReducedMotion, resolveElement } from "../../../lib/composables";
import { SPRING_GLIDE } from "../../../lib/ease";
import type { Hsva, Rgba } from "./color";
export const CHECKERBOARD =
  "repeating-conic-gradient(#d4d4d8 0% 25%, #fafafa 0% 50%) 0 0 / 8px 8px";
export const COLOR_MORPH = {
  type: "spring",
  duration: 0.5,
  bounce: 0.2,
} as const;
export interface ColorContext {
  id: string;
  hsva: Ref<Hsva>;
  rgba: Ref<Rgba>;
  hex: Ref<string>;
  open: Ref<boolean>;
  anchor: Ref<HTMLElement | null>;
  alpha: Ref<boolean>;
  disabled: Ref<boolean>;
  update: (next: Partial<Hsva>) => void;
  setColor: (value: string) => void;
  commit: () => void;
}
export function usePicker() {
  const state = inject<ColorContext>("orvui-color-picker");
  if (!state) throw Error("Color picker parts must be inside ColorPicker");
  return state;
}
export function useGlide(target: Ref<number>) {
  const reduced = useReducedMotion();
  const source = motionValue(target.value);
  const spring = useSpring(source, SPRING_GLIDE);
  const offset = useTransform(spring, (value) => `${value}%`);
  watch(
    [target, reduced],
    ([value, reduced]) => {
      if (reduced) {
        source.jump(value);
        spring.jump(value);
      } else source.set(value);
    },
    { immediate: true },
  );
  onBeforeUnmount(() => {
    offset.destroy();
    spring.destroy();
    source.destroy();
  });
  return { spring, offset };
}
export function useColorDrag(
  onPoint: (x: number, y: number) => void,
  onEnd: () => void,
  disabled: Ref<boolean>,
) {
  const rail = ref<unknown>(null);
  const thumb = ref<HTMLElement | null>(null);
  const dragging = ref(false);
  let contact: { id: number; element: HTMLElement } | undefined;
  const clamp = (value: number) => Math.min(1, Math.max(0, value));
  function sample(event: PointerEvent) {
    const box = resolveElement<HTMLElement>(
      rail.value,
    )?.getBoundingClientRect();
    if (box?.width && box.height)
      onPoint(
        clamp((event.clientX - box.left) / box.width),
        clamp((event.clientY - box.top) / box.height),
      );
  }
  function release() {
    const previous = contact;
    contact = undefined;
    dragging.value = false;
    if (previous)
      try {
        previous.element.releasePointerCapture(previous.id);
      } catch {
        /* Capture may already be lost. */
      }
  }
  function down(event: PointerEvent) {
    if (disabled.value || event.button !== 0 || contact) return;
    const element = event.currentTarget as HTMLElement;
    contact = { id: event.pointerId, element };
    dragging.value = true;
    try {
      element.setPointerCapture(event.pointerId);
    } catch {
      /* Synthetic pointer event. */
    }
    thumb.value?.focus({ preventScroll: true });
    sample(event);
  }
  function move(event: PointerEvent) {
    if (!disabled.value && contact?.id === event.pointerId) sample(event);
  }
  function end(event: PointerEvent) {
    if (contact?.id !== event.pointerId) return;
    release();
    if (!disabled.value) onEnd();
  }
  watch(disabled, (blocked) => {
    if (blocked) release();
  });
  onBeforeUnmount(release);
  return { rail, thumb, dragging, down, move, end };
}
export function keyStep(
  event: KeyboardEvent,
  big = 10,
): { axis: "x" | "y"; delta: number } | "min" | "max" | null {
  if (event.key === "Home") return "min";
  if (event.key === "End") return "max";
  const move = (
    {
      ArrowRight: ["x", 1],
      ArrowLeft: ["x", -1],
      ArrowUp: ["y", 1],
      ArrowDown: ["y", -1],
      PageUp: ["y", 1],
      PageDown: ["y", -1],
    } as const
  )[event.key as "ArrowRight"];
  return move
    ? {
        axis: move[0],
        delta:
          move[1] * (event.shiftKey || event.key.startsWith("Page") ? big : 1),
      }
    : null;
}

type Point = { x: number; y: number };

/** Keep consecutive preset transitions curving toward the same visual side. */
export function createPresetArc() {
  let curvature: number | undefined;
  return (from: Point, to: Point) => {
    const horizontal = to.x - from.x;
    const vertical = to.y - from.y;
    const horizontalTravel = Math.abs(horizontal) >= Math.abs(vertical);
    const dominant = horizontalTravel ? horizontal : vertical;
    let bend = dominant < 0 ? 0.3 : -0.3;
    let normalX = -vertical * bend;
    let normalY = horizontal * bend;
    const side = Math.sign(horizontalTravel ? normalY : normalX);
    if (curvature === undefined && side !== 0) curvature = side;
    else if (side !== 0 && curvature !== side) {
      normalX = -normalX;
      normalY = -normalY;
    }
    return (progress: number): Point => {
      const bow = 2 * progress * (1 - progress);
      return {
        x: from.x + horizontal * progress + normalX * bow,
        y: from.y + vertical * progress + normalY * bow,
      };
    };
  };
}

import { usePicker } from "./context";
/** Public context accessor for custom color-picker parts. */
export const useColorPicker = () => usePicker();

@import "tailwindcss";
@import "./tokens.css";
@source "./**/*.{vue,ts}";
@source not "./**/tests/**";
@custom-variant dark (&:where(.dark, .dark *));

:root { --announcement-h: 2.5rem; }

@theme {
  --background-image-brand-bg: var(--gradient-bg);
  --background-image-brand-accent: var(--gradient-accent);
  --animate-marquee: marquee 30s linear infinite;
  --animate-marquee-vertical: marquee-vertical 30s linear infinite;
  --animate-rainbow-border: rainbow-border 3s linear infinite;
  --animate-shimmer: shimmer 2.5s linear infinite;
  --animate-action-send: action-send 520ms var(--ease-out) both;
  --animate-action-copy: action-copy 520ms var(--ease-out) both;
  --animate-action-download: action-download 540ms var(--ease-out) both;
  --animate-action-archive: action-archive 520ms var(--ease-out) both;
  --animate-action-bell: action-bell 680ms var(--ease-out) both;
  --animate-action-settings: action-settings 720ms var(--ease-out) both;
}

/* Named motion tracks are part of the public styling contract. */
@keyframes marquee { to { transform: translateX(calc(-100% - var(--gap, 1rem))); } }
@keyframes marquee-vertical { to { transform: translateY(calc(-100% - var(--gap, 1rem))); } }
@keyframes rainbow-border {
  from { background-position: 0% 50%; }
  to { background-position: 100% 50%; }
}
@keyframes shimmer {
  from { background-position: 200% 0; }
  to { background-position: -200% 0; }
}
@keyframes action-send {
  0%, 100% { transform: translate(0, 0); }
  45% { transform: translate(2px, -2px); }
}
@keyframes action-copy {
  0%, 100% { transform: translate(0, 0); }
  40% { transform: translate(1.5px, -1.5px); }
  70% { transform: translate(-1px, 1px); }
}
@keyframes action-download {
  0%, 100% { transform: translateY(0); }
  42% { transform: translateY(2.5px); }
}
@keyframes action-archive {
  0%, 100% { transform: scale(1); }
  45% { transform: scale(0.9); }
}
@keyframes action-bell {
  0%, 100% { transform: rotate(0deg); }
  18% { transform: rotate(14deg); }
  36% { transform: rotate(-12deg); }
  54% { transform: rotate(8deg); }
  72% { transform: rotate(-5deg); }
}
@keyframes action-settings {
  from { transform: rotate(0deg); }
  to { transform: rotate(90deg); }
}

@layer base {
  html, body { overflow-x: clip; }
  html { color-scheme: light dark; }
  body {
    font-family: var(--font-sans);
    color: var(--foreground);
    background: var(--background);
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }
  a, button:not(:disabled), [role="button"]:not(:disabled) { cursor: pointer; }
  ::selection {
    color: var(--foreground);
    background: color-mix(in oklch, var(--accent) 30%, transparent);
  }
  .shiki, .shiki span { color: var(--shiki-light); }
  .dark .shiki, .dark .shiki span { color: var(--shiki-dark); }
}

@layer utilities {
  .text-balance { text-wrap: balance; }
  .text-pretty { text-wrap: pretty; }
  .scrollbar-hide { scrollbar-width: none; }
  .scrollbar-hide::-webkit-scrollbar { display: none; }
  .mask-b-fade { mask-image: linear-gradient(to bottom, black 60%, transparent); }
  .mask-radial-fade { mask-image: radial-gradient(ellipse at center, black 40%, transparent 75%); }
  .grid-noise {
    background-size: 32px 32px;
    background-image: linear-gradient(to right, color-mix(in oklch, var(--foreground) 6%, transparent) 1px, transparent 1px), linear-gradient(to bottom, color-mix(in oklch, var(--foreground) 6%, transparent) 1px, transparent 1px);
  }
  .glass {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    backdrop-filter: blur(20px) saturate(160%);
    box-shadow: inset 0 1px 0 0 rgb(255 255 255 / 0.06), 0 24px 60px -24px rgb(0 0 0 / 0.45);
  }
  .glass-strong { background: var(--glass-strong-bg); backdrop-filter: blur(16px); }
  .glass-thin { background: var(--glass-thin-bg); backdrop-filter: blur(12px); border: 1px solid var(--glass-border); }
  .press { transition: transform 120ms var(--ease-out); }
  .press:active { transform: scale(0.97); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

